components.css:
.ds-btn-primary { background: #67E8F9; color: #06222A; height: 44px; padding: 0 20px; border: 0; border-radius: 12px; font: 700 15px/1 Manrope, sans-serif; cursor: pointer; transition: background 150ms ease; }
.ds-btn-primary:hover { background: #8DEFFB; }
.ds-btn-primary:focus-visible { outline: 2px solid #67E8F9; outline-offset: 2px; }

.ds-btn-secondary { background: #0F1218; color: #E6E9EF; height: 44px; padding: 0 20px; border: 1px solid #262B36; border-radius: 12px; font: 700 15px/1 Manrope, sans-serif; cursor: pointer; transition: border-color 150ms ease, background 150ms ease; }
.ds-btn-secondary:hover { border-color: #7D8594; background: #141820; }
.ds-btn-secondary:focus-visible { outline: 2px solid #67E8F9; outline-offset: 2px; }

.ds-btn-ghost { background: transparent; color: #AEB5C2; height: 44px; padding: 0 20px; border: 0; border-radius: 12px; font: 700 15px/1 Manrope, sans-serif; cursor: pointer; transition: background 150ms ease, color 150ms ease; }
.ds-btn-ghost:hover { background: #141820; color: #E6E9EF; }
.ds-btn-ghost:focus-visible { outline: 2px solid #67E8F9; outline-offset: 2px; }

.ds-chips { display: flex; gap: 8px; }
.ds-chip { display: inline-flex; align-items: center; height: 36px; padding: 0 14px; border: 1px solid #262B36; border-radius: 999px; color: #AEB5C2; font: 700 13px/1 Manrope, sans-serif; cursor: pointer; transition: border-color 150ms ease, color 150ms ease, background 150ms ease; }
.ds-chip:hover { border-color: #7D8594; color: #E6E9EF; }
.ds-chip-on { background: #0E1E24; border-color: #67E8F9; color: #67E8F9; }

.ds-card { background: #0F1218; border: 1px solid #1C2029; border-radius: 14px; padding: 20px; display: flex; flex-direction: column; gap: 6px; font-family: Manrope, sans-serif; }
.ds-card-k { color: #7D8594; font-size: 13px; font-weight: 500; }
.ds-card-v { color: #E6E9EF; font: 700 32px/1.1 Sora, sans-serif; font-variant-numeric: tabular-nums; }
.ds-card-s { color: #4ADE80; font-size: 13px; font-weight: 600; }

.ds-input { background: #0F1218; color: #E6E9EF; height: 40px; padding: 0 14px; border: 1px solid #262B36; border-radius: 12px; font: 500 13px/1 Manrope, sans-serif; outline: none; transition: border-color 150ms ease; }
.ds-input::placeholder { color: #7D8594; }
.ds-input:focus { border-color: #67E8F9; }

.ds-nav { display: flex; flex-direction: column; gap: 6px; width: 220px; padding: 8px; background: #0A0C10; font-family: Manrope, sans-serif; }
.ds-nav a { display: flex; align-items: center; gap: 12px; padding: 10px; border-radius: 10px; color: #AEB5C2; font-size: 15px; font-weight: 600; cursor: pointer; }
.ds-nav a:hover { background: #0F1218; color: #E6E9EF; }
.ds-nav a svg { width: 20px; height: 20px; color: #7D8594; }
.ds-nav-on { background: #141820; color: #E6E9EF; }
.ds-nav-on svg { color: #67E8F9; }

.ds-dial { position: relative; width: 128px; height: 128px; font-family: Manrope, sans-serif; }
.ds-dial-svg { width: 100%; height: 100%; }
.ds-dial-in { position: absolute; inset: 0; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 6px; }
.ds-dial-n { color: #E6E9EF; font: 700 44px/1 Sora, sans-serif; font-variant-numeric: tabular-nums; }
.ds-dial-l { color: #7D8594; font-size: 12px; font-weight: 700; }
